CREATE TABLE IF NOT EXISTS notification_templates(id CHAR(36) PRIMARY KEY,template_code VARCHAR(100) NOT NULL,channel ENUM('SMS','EMAIL','PUSH','IN_APP') NOT NULL,subject_template VARCHAR(200) NULL,body_template TEXT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,version INT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),UNIQUE KEY uq_notification_template(template_code,channel,version));
CREATE TABLE IF NOT EXISTS notification_deliveries(id CHAR(36) PRIMARY KEY,customer_id CHAR(36) NULL,template_code VARCHAR(100) NOT NULL,channel ENUM('SMS','EMAIL','PUSH','IN_APP') NOT NULL,recipient_masked VARCHAR(254) NOT NULL,provider VARCHAR(100) NOT NULL,provider_reference VARCHAR(180) NULL,status ENUM('PENDING','DELIVERED','FAILED') NOT NULL,entity_type VARCHAR(80) NULL,entity_id VARCHAR(100) NULL,correlation_id VARCHAR(100) NULL,error_code VARCHAR(80) NULL,error_message VARCHAR(255) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),delivered_at DATETIME(3) NULL,INDEX idx_notification_delivery_time(created_at),INDEX idx_notification_customer_time(customer_id,created_at),INDEX idx_notification_status(status),FOREIGN KEY(customer_id) REFERENCES users(id) ON DELETE SET NULL);
